repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('plaza', 34), ('harbour', 10), ('lodge', 25), ('harbour', 58), ('grand', 38)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.pages.py:
"""Pages of bookings."""


def page_count(n_items, page_size):
    """Return how many pages are needed to show n_items, page_size to a page."""
    return n_items // page_size


def page(bookings, number, page_size):
    """Return page `number` of bookings. Pages are numbered from 1."""
    start = (number - 1) * page_size
    return bookings[start:start + page_size]


def all_pages(bookings, page_size):
    """Return every page of bookings, in order."""
    return [page(bookings, n, page_size) for n in range(1, page_count(len(bookings), page_size) + 1)]


def describe_booking(booking):
    """Return a one-line description of a booking."""
    return "%s: %s" % (booking.hotel, booking.nights)
